package com.kittyai.assistant;

import android.app.*; import android.content.*; import android.os.*; import android.speech.*; import java.util.*;
/** Experimental wake phrase listener. Android may stop/restrict background microphone use. */
public class WakeWordService extends Service {
 public static volatile boolean running=false; private SpeechRecognizer sr; private boolean listening=false; private static final String CHANNEL="kitty_wake";
 @Override public void onCreate(){super.onCreate();createChannel(); Notification n=new Notification.Builder(this,CHANNEL).setContentTitle("Kitty AI").setContentText("Hey Kitty wake listening enabled").setSmallIcon(android.R.drawable.ic_btn_speak_now).build();startForeground(71,n);running=true; startListen();}
 private void createChannel(){if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(CHANNEL,"Kitty wake listener",NotificationManager.IMPORTANCE_LOW);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c);}}
 private void startListen(){if(!SpeechRecognizer.isRecognitionAvailable(this))return;try{if(sr!=null)sr.destroy();sr=SpeechRecognizer.createSpeechRecognizer(this);sr.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle b){} public void onBeginningOfSpeech(){} public void onRmsChanged(float f){} public void onBufferReceived(byte[] b){} public void onEndOfSpeech(){listening=false;} public void onError(int e){listening=false; if(running)new Handler(Looper.getMainLooper()).postDelayed(()->startListen(),1200);} public void onResults(Bundle b){listening=false;ArrayList<String> a=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(a!=null)for(String s:a)if(s.toLowerCase(Locale.ROOT).contains("hey kitty")||s.toLowerCase(Locale.ROOT).contains("ஹே கிட்டி")){Intent i=new Intent(WakeWordService.this,MainActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP);startActivity(i);break;}if(running)new Handler(Looper.getMainLooper()).postDelayed(()->startListen(),700);}public void onPartialResults(Bundle b){}public void onEvent(int e,Bundle b){}});Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"en-US");i.putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,false);sr.startListening(i);listening=true;}catch(Exception e){listening=false;}}
 @Override public int onStartCommand(Intent i,int f,int id){return START_STICKY;} @Override public void onDestroy(){running=false;if(sr!=null)sr.destroy();super.onDestroy();} @Override public IBinder onBind(Intent i){return null;}
}
